def load_enriched_jsonl(path: str) -> list[Sample]:
    samples = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                samples.append(Sample(**json.loads(line)))
    return samples

